const input = $input.first().json; // take previous node json 
const output = JSON.parse(JSON.stringify(input)); // verfiy the json 

// Track current category
if (typeof output.currentCategoryIndex !== "number") { // add fallback index value for array  
  output.currentCategoryIndex = 0;
}

const currentCategory = output.categories[output.currentCategoryIndex]; // access categories object 

// Initialize working batch size from category/chapter count
if (typeof output.currentWorkingBatchSize !== "number") { // 
  output.currentWorkingBatchSize =
    currentCategory.chapters?.[0]?.generationConfig?.batchSize ||
    currentCategory.questionCount ||
    0;
}

// Process ONE question
output.currentWorkingBatchSize--;

// Category/chapter completed
if (output.currentWorkingBatchSize <= 0) {

  // Decrement GLOBAL counter ONLY after category completion
  output.generationConfig.batchSize--;

  // Move to next category
  output.currentCategoryIndex++;

  // Load next category
  if (output.currentCategoryIndex < output.categories.length) {

    const nextCategory =
      output.categories[output.currentCategoryIndex];

    output.currentWorkingBatchSize =
      nextCategory.chapters?.[0]?.generationConfig?.batchSize ||
      nextCategory.questionCount ||
      0;

  } else {

    output.isComplete = true;
    output.currentCategoryIndex =
      output.categories.length - 1;

    output.currentWorkingBatchSize = 0;
  }
}

return [
  {
    json: {
      generationConfig: output.generationConfig,
      metadata: output.metadata,

      categories: [
        output.categories[output.currentCategoryIndex]
      ],

      questionDistribution: output.questionDistribution,
      responseSchema: output.responseSchema,

      currentCategoryIndex: output.currentCategoryIndex,
      currentWorkingBatchSize: output.currentWorkingBatchSize,
      isComplete: output.isComplete || false
    }
  }
];

