function addNullIds(obj) {

  if (Array.isArray(obj.categories)) {
    obj.categories.forEach(category => {

      category.id = null;

      if (Array.isArray(category.chapters)) {
        category.chapters.forEach(chapter => {

          chapter.id = null;

          if (Array.isArray(chapter.topics)) {
            chapter.topics.forEach(topic => {

              if (!Object.prototype.hasOwnProperty.call(topic, 'id')) {
                topic.id = null;
              } else {
                topic.id = null;
              }
            });
          }
        });
      }
    });
  }

  return obj;
}

return [{
  json: addNullIds(data)
}];

