try {

  const data = $input.first().json;

  console.log("Input:", JSON.stringify(data, null, 2));

  if (data.isComplete) {
    return [];
  }

  if (!data.categories) {
    throw new Error("categories is missing");
  }

  if (data.currentCategoryIndex === undefined) {
    throw new Error("currentCategoryIndex is missing");
  }

  const currentCategory =
    data.categories[data.currentCategoryIndex];

  if (!currentCategory) {
    throw new Error(
      `No category found at index ${data.currentCategoryIndex}`
    );
  }

  const loopCount =
    Number(data.currentWorkingBatchSize);

  if (!loopCount || loopCount < 1) {
    throw new Error(
      `Invalid currentWorkingBatchSize: ${data.currentWorkingBatchSize}`
    );
  }

  const items = [];

  for (let i = 1; i <= loopCount; i++) {

    items.push({
      json: {
        iteration: i,
        totalIterations: loopCount,

        currentCategoryIndex:
          data.currentCategoryIndex,

        currentWorkingBatchSize:
          data.currentWorkingBatchSize,

        categoryId: currentCategory.id,
        categoryName: currentCategory.name,

        category: currentCategory
      }
    });

  }

  return items;

} catch (error) {

  return [
    {
      json: {
        error: true,
        message: error.message,
        stack: error.stack
      }
    }
  ];

}

