const data = $input.first().json;

// ----------------------------
// Defaults
// ----------------------------

data.loopInfo ??= {
  currentCategoryIndex: 0,
  currentChapterIndex: 0,
  currentTopicIndex: 0,

  currentDifficultyIndex: 0,
  currentQuestionTypeIndex: 0,

  currentWorkingBatchSize: 0
};

const difficultyOrder = [
  "easy",
  "moderate",
  "hard"
];

const questionTypeOrder = [
  "Single",
  "Multiple",
  "Numerical"
];

const categories = data.categories || [];

if (!categories.length) {
  data.isComplete = true;

  return [{ json: data }];
}

// ----------------------------
// Current Position
// ----------------------------

let categoryIndex =
  data.loopInfo.currentCategoryIndex;

let chapterIndex =
  data.loopInfo.currentChapterIndex;

let topicIndex =
  data.loopInfo.currentTopicIndex;

let difficultyIndex =
  data.loopInfo.currentDifficultyIndex;

let questionTypeIndex =
  data.loopInfo.currentQuestionTypeIndex;

// ----------------------------
// Current Context
// ----------------------------

const category =
  categories[categoryIndex];

const chapter =
  category.chapters[chapterIndex];

const topic =
  chapter.topics[topicIndex];

const difficulty =
  difficultyOrder[difficultyIndex];

const optionType =
  questionTypeOrder[questionTypeIndex];

// ----------------------------
// Question Count
// ----------------------------
console.log("difficulty console", chapter)
const questionCount =
  chapter.generationconfig
    ?.difficultydistribution?.[
      difficulty
    ] || 0;
console.log("questionCount", questionCount); 
// ----------------------------
// Build Loop Items
// ----------------------------

const loopItems = [];

for (
  let questionNumber = 1;
  questionNumber <= questionCount;
  questionNumber++
) {
  loopItems.push({
    categoryId: category.id,
    categoryName: category.name,

    chapterId: chapter.id,
    chapterName: chapter.name,

    topicId: topic.id,
    topicName: topic.name,

    subtopicsName:
      topic.subtopics,

    optionType:
      optionType,

    difficultyLevel:
      difficulty,

    questionNumber,

    responseSchema:
      data.responseschema
  });
}

// ----------------------------
// Save Current Batch
// ----------------------------

data.loopItems = loopItems;

data.loopInfo.currentWorkingBatchSize =
  loopItems.length;

data.loopInfo.currentCombination =
  `${difficulty}-${optionType}`;

// ----------------------------
// Advance State
// ----------------------------

questionTypeIndex++;

if (
  questionTypeIndex >=
  questionTypeOrder.length
) {
  questionTypeIndex = 0;
  difficultyIndex++;
}

if (
  difficultyIndex >=
  difficultyOrder.length
) {
  difficultyIndex = 0;
  topicIndex++;

  if (
    topicIndex >=
    chapter.topics.length
  ) {
    topicIndex = 0;
    chapterIndex++;

    if (
      chapterIndex >=
      category.chapters.length
    ) {
      chapterIndex = 0;
      categoryIndex++;

      if (
        categoryIndex >=
        categories.length
      ) {
        data.isComplete = true;
      }
    }
  }
}

// ----------------------------
// Save Next State
// ----------------------------

data.loopInfo.currentCategoryIndex =
  categoryIndex;

data.loopInfo.currentChapterIndex =
  chapterIndex;

data.loopInfo.currentTopicIndex =
  topicIndex;

data.loopInfo.currentDifficultyIndex =
  difficultyIndex;

data.loopInfo.currentQuestionTypeIndex =
  questionTypeIndex;

// ----------------------------
// Return
// ----------------------------

return [
  {
    json: data
  }
];

