// ------------------------------------------------------------
// Remove xmlns from all MathML
// ------------------------------------------------------------

function cleanMathML(mathml) {

	if (typeof mathml !== "string") {
		return mathml;
	}

	return mathml
		.replace(/\s+xmlns="http:\/\/www\.w3\.org\/1998\/Math\/MathML"/g, "")
		.trim();
}

conversions.forEach((conversion, index) => {

	if (!conversion.success) {
		throw new Error(`Conversion ${index + 1} failed.`);
	}

	if (!Array.isArray(conversion.data)) {
		throw new Error(
			`Conversion ${index + 1} does not contain data[].`
		);
	}

	conversion.data.forEach(item => {

		if (typeof item.mathml === "string") {
			item.mathml = cleanMathML(item.mathml);
		}

	});
});

// ------------------------------------------------------------
// Inject MathML recursively
// ------------------------------------------------------------

function injectMathML(value, latexMap) {

	if (typeof value === "string") {

		return value.replace(/\{\{latex\[(\d+)\]\}\}/g, (_, index) => {

			index = Number(index);

			if (!latexMap[index]) {
				throw new Error(
					`Missing latex index ${index}`
				);
			}

			return latexMap[index].mathml;
		});
	}

	if (Array.isArray(value)) {
		return value.map(v => injectMathML(v, latexMap));
	}

	if (value && typeof value === "object") {

		Object.keys(value).forEach(key => {
			value[key] = injectMathML(value[key], latexMap);
		});

		return value;
	}

	return value;
}

// ------------------------------------------------------------
// Merge
// ------------------------------------------------------------

questions.forEach((question, questionIndex) => {

	const conversion = conversions[questionIndex];

	if (!Array.isArray(question.latex)) {
		throw new Error(
			`Question ${questionIndex + 1} does not contain latex[].`
		);
	}

	if (question.latex.length !== conversion.data.length) {
		throw new Error(
			[
				`Latex length mismatch`,
				`Question ${questionIndex + 1}`,
				`Question Latex Count : ${question.latex.length}`,
				`MathML Count : ${conversion.data.length}`
			].join("\n")
		);
	}

	const mergedLatex = question.latex.map((latexString, latexIndex) => {

		const converted = conversion.data[latexIndex];

		if (!converted) {
			throw new Error(
				`Missing MathML for Question ${questionIndex + 1}, Latex ${latexIndex}`
			);
		}

		if (latexString !== converted.latex) {
			throw new Error(
				[
					`Latex mismatch`,
					`Question : ${questionIndex + 1}`,
					`Latex Index : ${latexIndex}`,
					`Expected : ${latexString}`,
					`Received : ${converted.latex}`
				].join("\n")
			);
		}

		return {
			latex: converted.latex,
			mathml: converted.mathml
		};

	});

	// Replace placeholders recursively
	injectMathML(question, mergedLatex);

	// Replace latex array with merged objects
	question.latex = mergedLatex;

});

// ------------------------------------------------------------
// Return in the same structure as input
// ------------------------------------------------------------

return [
	{
		json: {
			haveLatex: questions
		}
	}
];

