// const [firstItem, ...secondItem] = items; 
// console.log("firstItem", firstItem); 
// console.log("secondItem", secondItem); 


// return $input.all();
const items = $input.all().map(item => item.json);

const [config, ...lookup] = items;

const categoryMap = {};
const chapterMap = {};
const topicMap = {};

for (const item of lookup) {
  const key = item.name.trim().toLowerCase();

  if (item.type === "category") {
    categoryMap[key] = item.id;
  }

  if (item.type === "chapter") {
    chapterMap[key] = item.id;
  }

  if (item.type === "topic") {
    topicMap[key] = item.id;
  }
}

for (const category of config.categories) {

  category.id =
    categoryMap[category.name.trim().toLowerCase()] ?? null;

  for (const chapter of category.chapters) {

    chapter.id =
      chapterMap[chapter.name.trim().toLowerCase()] ?? null;

    for (const topic of chapter.topics) {

      topic.id =
        topicMap[topic.name.trim().toLowerCase()] ?? null;
    }
  }
}

return [{ json: config }];

// Loop over input items and add a new field called 'myNewField' to the JSON of each one
for (const item of $input.all()) {
  item.json.myNewField = 1;
}

return $input.all();

const fs = require("fs");

// const JSON_PATH = "/home/node/.n8n-files/deep-seek-json.json";
// const JSON_PATH = "/home/node/.n8n-files/update-initial-json.json";
// const JSON_PATH = "/home/node/.n8n-files/update-deepseek.json";
const JSON_PATH = "/home/node/.n8n-files/update-another-deepseek.json";
const STATE_PATH = "/home/node/.n8n-files/state.json";

//-----------------------------------------------------
// Load Initial JSON
//-----------------------------------------------------
const root = JSON.parse(fs.readFileSync(JSON_PATH, "utf8"));

const data = Array.isArray(root) ? root[0] : root;

if (!data.categories || !Array.isArray(data.categories)) {
  throw new Error("Invalid JSON: categories array not found.");
}

//-----------------------------------------------------
// Load/Create State
//-----------------------------------------------------

let state = {
  currentCategoryIndex: 0,
  currentChapterIndex: 0,
  currentTopicIndex: 0,
};

if (fs.existsSync(STATE_PATH)) {
  state = JSON.parse(fs.readFileSync(STATE_PATH, "utf8"))
}

//-----------------------------------------------------
// Current Objects
//-----------------------------------------------------

if (state.currentCategoryIndex >= data.categories.length) {
  throw new Error(
    `Invalid currentCategoryIndex: ${state.currentCategoryIndex}`
  );
}

const category = data.categories[state.currentCategoryIndex];

if (!category.chapters || !Array.isArray(category.chapters)) {
  throw new Error(`Category '${category.name}' has no chapters.`);
}

if (state.currentChapterIndex >= category.chapters.length) {
  throw new Error(
    `Invalid currentChapterIndex: ${state.currentChapterIndex}`
  );
}

const chapter = category.chapters[state.currentChapterIndex];

if (!chapter.topics || !Array.isArray(chapter.topics)) {
  throw new Error(`Chapter '${chapter.name}' has no topics.`);
}

if (state.currentTopicIndex >= chapter.topics.length) {
  throw new Error(
    `Invalid currentTopicIndex: ${state.currentTopicIndex}`
  );
}

const topic = chapter.topics[state.currentTopicIndex];

//-----------------------------------------------------
// Create Loop Item
//-----------------------------------------------------

const loopItem = {
  categoryId: category.id,
  categoryName: category.name,

  chapterId: chapter.id,
  chapterName: chapter.name,

  topicId: topic.id,
  topicName: topic.name,

  subtopicsName: topic.subtopics,

 optionType: chapter.generationconfig.perbatchdistribution.questiontype,

difficultyLevel: chapter.generationconfig.perbatchdistribution.difficulty,
//TODO: chapter.generationconfig.perbatchdistribution
  perbatchdistribution:
    chapter.generationconfig.perbatchdistribution,

  questionNumber:
    chapter.generationconfig.batchsize,

  responseSchema:
    data.responseschema
};

//-----------------------------------------------------
// Batch Values
//-----------------------------------------------------

/*
"perbatchdistribution": {
  "difficulty": {
    "easy": 2,
    "moderate": 3,
    "hard": 1
  },
  "questiontype": {
    "single": 4,
    "multiple": 1,
    "numerical": 1
  }
}
*/
const batch =
  chapter.generationconfig.perbatchdistribution; 
// value is 


const batchSize =
  chapter.generationconfig.batchsize; // 6 

//-----------------------------------------------------
// Update Global
//-----------------------------------------------------

data.generationconfig.totalquestions -= batchSize;
data.generationconfig.totalapicalls -= 1;

data.questiondistribution.difficulty.easy -=
  batch.difficulty.easy;

data.questiondistribution.difficulty.moderate -=
  batch.difficulty.moderate;

data.questiondistribution.difficulty.hard -=
  batch.difficulty.hard;

data.questiondistribution.questiontype.single -=
  batch.questiontype.single;

data.questiondistribution.questiontype.multiple -=
  batch.questiontype.multiple;

data.questiondistribution.questiontype.numerical -=
  batch.questiontype.numerical;

//-----------------------------------------------------
// Update Category
//-----------------------------------------------------

category.questioncount -= batchSize;
category.apicalls -= 1;

//-----------------------------------------------------
// Update Chapter
//-----------------------------------------------------

chapter.questioncount -= batchSize;
chapter.apicalls -= 1;

chapter.generationconfig.difficultydistribution.easy -=
  batch.difficulty.easy;

chapter.generationconfig.difficultydistribution.moderate -=
  batch.difficulty.moderate;

chapter.generationconfig.difficultydistribution.hard -=
  batch.difficulty.hard;

chapter.generationconfig.questiontypedistribution.single -=
  batch.questiontype.single;

