// Loop-safety + poison-fix for the Gemini retry branch.
// n8n appends an `error` object to the item on the error output. Because
// HTTP Request2 sends the whole json item as its body, that appended field
// poisons the retry (Gemini returns 400 "Unknown name error"). Here we rebuild
// a CLEAN request body and track a per-request retry counter (max 5) in
// workflow static data so the loop cannot run forever.
const staticData = $getWorkflowStaticData('global');
staticData.__geminiRetry ??= {};

const src = $input.first().json;

const body = {
  systemInstruction: src.systemInstruction,
  contents: src.contents,
  generationConfig: src.generationConfig
};

// Stable key so the counter is per-question, not global
const str = JSON.stringify(body.contents ?? body);
let h = 0;
for (let i = 0; i < str.length; i++) { h = (h * 31 + str.charCodeAt(i)) | 0; }
const key = String(h);

const MAX = 5;
const count = (staticData.__geminiRetry[key] || 0) + 1;
staticData.__geminiRetry[key] = count;
const exceeded = count > MAX;
if (exceeded) delete staticData.__geminiRetry[key];

return [{ json: { body, retryCount: count, maxRetries: MAX, exceeded } }];

// Loop over input items and add a new field called 'myNewField' to the JSON of each one
